const b = $input.item.json.body || {};
const err = (m) => ({ json: { valido: false, error: m } });

const ACCIONES = ['aprobar', 'rechazar', 'solicitar_informacion'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL = /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/;
const s = (v, max = 4000) => (typeof v === 'string' ? v.trim().slice(0, max) : '');

if (!ACCIONES.includes(b.accion)) return err('accion no válida (aprobar | rechazar | solicitar_informacion)');
if (!UUID.test(s(b.solicitud_id, 64))) return err('solicitud_id inválido');
if (!EMAIL.test(s(b.destinatario, 320))) return err('destinatario inválido');
if (!s(b.gmail_message_id, 200)) return err('gmail_message_id es obligatorio para responder en el mismo hilo');
if (b.accion === 'rechazar' && s(b.motivo).length < 5) return err('El motivo del rechazo es obligatorio');
if (b.accion === 'solicitar_informacion' && s(b.mensaje).length < 10) return err('El mensaje de solicitud de información es obligatorio');

return {
  json: {
    valido: true,
    accion: b.accion,
    solicitud_id: s(b.solicitud_id, 64),
    destinatario: s(b.destinatario, 320),
    nombre_destinatario: s(b.nombre_destinatario, 200),
    asunto_original: s(b.asunto_original, 500),
    gmail_message_id: s(b.gmail_message_id, 200),
    nombre_proyecto: s(b.nombre_proyecto, 300),
    decidido_por: s(b.decidido_por, 200),
    observaciones: s(b.observaciones),
    motivo: s(b.motivo),
    mensaje: s(b.mensaje),
    campos_faltantes: Array.isArray(b.campos_faltantes) ? b.campos_faltantes.map((c) => s(c, 80)).filter(Boolean).slice(0, 30) : [],
  },
};

const esc = (t) => String(t ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
  .replace(/\n/g, '<br>');
const envolver = (contenido) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2937;line-height:1.55">${contenido}
<p style="margin-top:24px">Cordialmente,<br><strong>Coordinación Académica</strong><br><span style="color:#6b7280;font-size:12px">Este mensaje fue enviado desde el sistema de gestión de solicitudes.</span></p></div>`;
const d = $input.item.json;
const saludo = d.nombre_destinatario ? `Estimado/a ${esc(d.nombre_destinatario)},` : 'Estimado/a solicitante,';
const proyecto = d.nombre_proyecto ? ` “${esc(d.nombre_proyecto)}”` : '';
const base = { solicitud_id: d.solicitud_id, destinatario: d.destinatario, gmail_message_id: d.gmail_message_id, asunto_original: d.asunto_original };

let html = `<p>${saludo}</p><p>Nos complace informarle que su solicitud${proyecto} ha sido <strong style="color:#15803d">APROBADA</strong>.</p>`;
if (d.observaciones) html += `<p><strong>Observaciones de la coordinación:</strong><br>${esc(d.observaciones)}</p>`;
html += '<p>Si necesita aclarar algún aspecto del proceso, puede responder directamente a este correo.</p>';
return { json: { ...base, tipo: 'Aprobación', html: envolver(html) } };

