const saludo = d.nombre_destinatario ? `Estimado/a ${esc(d.nombre_destinatario)},` : 'Estimado/a solicitante,';
const proyecto = d.nombre_proyecto ? ` “${esc(d.nombre_proyecto)}”` : '';
const base = { solicitud_id: d.solicitud_id, destinatario: d.destinatario, gmail_message_id: d.gmail_message_id, asunto_original: d.asunto_original };

let html = `<p>${saludo}</p><p>Después de revisar su solicitud${proyecto}, lamentamos informarle que no ha sido aprobada.</p>`;
html += `<p><strong>Motivo:</strong><br>${esc(d.motivo)}</p>`;
if (d.observaciones) html += `<p><strong>Observaciones adicionales:</strong><br>${esc(d.observaciones)}</p>`;
html += '<p>Puede responder a este correo si desea ampliar la información o presentar una nueva propuesta.</p>';
return { json: { ...base, tipo: 'Rechazo', html: envolver(html) } };

