<p style="margin-top:24px">Cordialmente,<br><strong>Coordinación Académica</strong><br><span style="color:#6b7280;font-size:12px">Este mensaje fue enviado desde el sistema de gestión de solicitudes.</span></p></div>`;
const d = $input.item.json;
const saludo = d.nombre_destinatario ? `Estimado/a ${esc(d.nombre_destinatario)},` : 'Estimado/a solicitante,';
const proyecto = d.nombre_proyecto ? ` “${esc(d.nombre_proyecto)}”` : '';
const base = { solicitud_id: d.solicitud_id, destinatario: d.destinatario, gmail_message_id: d.gmail_message_id, asunto_original: d.asunto_original };

let html = `<p>${saludo}</p><p>Para continuar con la revisión de su solicitud${proyecto} necesitamos información adicional.</p>`;
if (d.campos_faltantes.length) {
  html += '<p><strong>Datos que faltan:</strong></p><ul>' + d.campos_faltantes.map((c) => `<li>${esc(c)}</li>`).join('') + '</ul>';
}
html += `<p>${esc(d.mensaje)}</p><p>Por favor responda a este mismo correo con la información solicitada.</p>`;
return { json: { ...base, tipo: 'Información', html: envolver(html) } };

// Recupera el correo redactado en la rama que se ejecutó
const ramas = ['Redactar aprobación', 'Redactar rechazo', 'Redactar solicitud de información'];
let r = null;
for (const n of ramas) {
  try { const it = $(n).item; if (it) { r = it.json; break; } } catch (e) { /* rama no ejecutada */ }
}
if (!r) throw new Error('No se pudo recuperar el correo redactado');
const enviado = $input.item.json;
const texto = r.html.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li)>/gi, '\n').replace(/<[^>]+>/g, '').replace(/\n{3,}/g, '\n\n').trim();
return {
  json: {
    solicitud_id: r.solicitud_id,
    destinatario: r.destinatario,
    asunto: 'Re: ' + (r.asunto_original || ''),
    cuerpo: texto,
    tipo: r.tipo,
    gmail_message_id: enviado.id || null,
    estado_envio: 'Enviado',
  },
};

const ramas = ['Redactar aprobación', 'Redactar rechazo', 'Redactar solicitud de información'];
let r = null;
for (const n of ramas) {
  try { const it = $(n).item; if (it) { r = it.json; break; } } catch (e) { /* rama no ejecutada */ }
}
const e = $input.item.json.error || {};
const mensaje = String(e.message || e.description || 'Error desconocido al enviar con Gmail').slice(0, 500);
return {
  json: {
    solicitud_id: r.solicitud_id,
    destinatario: r.destinatario,
    asunto: 'Re: ' + (r.asunto_original || ''),
    cuerpo: '(no enviado)',
    tipo: r.tipo,
    gmail_message_id: null,
    estado_envio: 'Error',
    error_detalle: mensaje,
  },
};
